CREATE DATABASE IF NOT EXISTS student_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_portal;
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,student_code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,course VARCHAR(100) DEFAULT 'BCA',semester INT DEFAULT 1,email VARCHAR(150) NOT NULL,phone VARCHAR(30),image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','student') NOT NULL,name VARCHAR(150) NOT NULL,student_id INT NULL,status TINYINT DEFAULT 1,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL);
CREATE TABLE marks(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,semester INT NOT NULL,subject VARCHAR(150) NOT NULL,marks INT NOT NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE questions(id INT AUTO_INCREMENT PRIMARY KEY,question TEXT NOT NULL,option_a VARCHAR(255) NOT NULL,option_b VARCHAR(255) NOT NULL,option_c VARCHAR(255) NOT NULL,option_d VARCHAR(255) NOT NULL,correct_answer CHAR(1) NOT NULL,active TINYINT DEFAULT 1);
CREATE TABLE queries(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,reply TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,replied_at DATETIME NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
